\path[use as bounding box] (-2,-3.1) rectangle (9,3.1);
\draw[black,line width=0.5pt,->] (-1.8,0)--(8.5,0) node[right] {$x$};

% Filled 0.5pt shaft avoids a zero-area stroked-axis PDF paint failure.
\path[fill=black,draw=none] ([xshift=-0.25pt]0,-2.7) rectangle ([xshift=0.25pt]0,2.7);
\draw[black,line width=0.5pt,->] (0,-2.7)--(0,2.7) node[above] {$y$};
\draw[black,line width=0.4pt,dashed] (4,-2.7)--(4,2.7) node[above] {$x=4$};
\node[below right] at (7.5,0) {$y=0$};
\draw[black,line width=0.8pt,samples=100,domain=-1.7:3.62] plot (\x,{1/(\x-4)});
\draw[black,line width=0.8pt,samples=100,domain=4.38:8.2] plot (\x,{1/(\x-4)});
\fill[black] (0,-0.25) circle (1.2pt);
\node[below left] at (0,-0.25) {$(0,-\frac14)$};
\end{tikzpicture}

